args.despues:
def __init__(self) -> None:
    # Indexado por id, igual que la clave primaria de PostgreSQL.
    self._reportes: dict[str, Reporte] = {}

def guardar_si_no_existe(self, reporte: Reporte) -> bool:
    # Equivale a ON CONFLICT (id) DO NOTHING: un reenvío con el mismo id no duplica.
    if reporte.id in self._reportes:
        return False
    self._reportes[reporte.id] = reporte
    return True

def contar(self) -> int:
    return len(self._reportes)
